import { Controller } from '@nestjs/common';

// 이 기능(FN-SFR-004-05)이 새로 만드는 API는 없다.
// GET /expense-resolutions, POST /expense-resolutions 는 다른 기능이 만든다.
@Controller('api/v1')
export class FnSfr00405Controller {}

