import { useState } from 'react';
import type { PageProps, Row, Page } from '../kit';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  NumberInput,
  DateInput,
  Select,
  LookupSelect,
} from '../kit';

const SIZE = 20;

const STATUSES: [string, string][] = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'].map(
  (s): [string, string] => [s, s],
);

const EVIDENCES: [string, string][] = ['통장', '카드', '현금영수증', '전자세금계산서'].map(
  (s): [string, string] => [s, s],
);

interface Applied {
  projectId: number | string;
  approvalStatus: string;
}

const EMPTY_FORM: Row = {
  resolutionDate: '',
  purchaseRequestId: '',
  projectId: '',
  budgetItemId: '',
  amount: '',
  evidenceType: '',
  partnerId: '',
  departmentId: '',
};

export default function FnSfr00405Page({ role, notify }: PageProps) {
  const [projectId, setProjectId] = useState<number | string>('');
  const [approvalStatus, setApprovalStatus] = useState('');
  const [applied, setApplied] = useState<Applied>({ projectId: '', approvalStatus: '' });
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [form, setForm] = useState<Row>(EMPTY_FORM);

  const { data, error, loading, reload } = useData<Page>(
    () =>
      call<Page>('GET', '/expense-resolutions', role, undefined, {
        projectId: applied.projectId,
        approvalStatus: applied.approvalStatus,
        page,
        size: SIZE,
      }),
    [applied, page],
  );

  const items = data ? data.items : [];
  const total = data ? data.total : 0;
  const pageSum = items.reduce((sum, r) => sum + Number(r['amount'] ?? 0), 0);

  const setField = (key: string, value: unknown) => {
    setForm((prev) => ({ ...prev, [key]: value }));
  };

  const search = () => {
    setPage(0);
    setApplied({ projectId, approvalStatus });
  };

  const reset = () => {
    setProjectId('');
    setApprovalStatus('');
    setPage(0);
    setApplied({ projectId: '', approvalStatus: '' });
  };

  const openCreate = () => {
    setForm(EMPTY_FORM);
    setCreating(true);
  };

  const submit = async () => {
    const required: [string, string][] = [
      ['resolutionDate', '결의일자'],
      ['projectId', '프로젝트'],
      ['budgetItemId', '예산과목'],
      ['amount', '결의 금액'],
      ['evidenceType', '증빙 유형'],
      ['departmentId', '결의부서'],
    ];
    for (const [key, label] of required) {
      if (form[key] === '' || form[key] === undefined || form[key] === null) {
        throw new Error(label + '을(를) 입력하세요.');
      }
    }
    if (typeof form['amount'] !== 'number' || form['amount'] <= 0) {
      throw new Error('결의 금액은 0보다 큰 숫자로 입력하세요.');
    }
    await call('POST', '/expense-resolutions', role, form);
    notify('수입·지출 거래를 등록했습니다.');
    setCreating(false);
    setPage(0);
    reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={total} />],
            ['현재 쪽 결의 금액 합계', <Num value={pageSum} />],
          ]}
        />
      </section>

      <section className="box span-12">
        <h2>수입·지출 내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="프로젝트">
            <LookupSelect
              table="project"
              role={role}
              value={projectId}
              onChange={setProjectId}
              placeholder="전체"
            />
          </Field>
          <Field label="결재 상태">
            <Select
              value={approvalStatus}
              onChange={setApprovalStatus}
              options={STATUSES}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={openCreate}>
            거래 등록
          </button>
        </Band>
        {error ? <p>{error}</p> : null}
        <DataTable
          columns={[
            { key: 'documentNo', label: '문서번호' },
            { key: 'resolutionDate', label: '결의일자', render: (r) => <DateText value={r['resolutionDate']} /> },
            { key: 'amount', label: '결의 금액', render: (r) => <Num value={r['amount']} /> },
            { key: 'approvalStatus', label: '결재 상태', render: (r) => <Badge value={r['approvalStatus']} /> },
          ]}
          rows={items}
          empty={loading ? '불러오는 중입니다.' : '조회된 내역이 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>

      {creating ? (
        <Drawer title="수입·지출 거래 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={submit} submit="등록">
            <Field label="결의일자" required>
              <DateInput value={form['resolutionDate']} onChange={(v) => setField('resolutionDate', v)} />
            </Field>
            <Field label="결의부서" required>
              <LookupSelect
                table="department"
                role={role}
                value={form['departmentId']}
                onChange={(v) => setField('departmentId', v)}
              />
            </Field>
            <Field label="프로젝트" required>
              <LookupSelect
                table="project"
                role={role}
                value={form['projectId']}
                onChange={(v) => setField('projectId', v)}
              />
            </Field>
            <Field label="예산과목" required>
              <LookupSelect
                table="budget_item"
                role={role}
                value={form['budgetItemId']}
                onChange={(v) => setField('budgetItemId', v)}
              />
            </Field>
            <Field label="결의 금액" required>
              <NumberInput value={form['amount']} onChange={(v) => setField('amount', v)} />
            </Field>
            <Field label="증빙 유형" required>
              <Select
                value={form['evidenceType']}
                onChange={(v) => setField('evidenceType', v)}
                options={EVIDENCES}
              />
            </Field>
            <Field label="거래처">
              <LookupSelect
                table="partner"
                role={role}
                value={form['partnerId']}
                onChange={(v) => setField('partnerId', v)}
              />
            </Field>
            <Field label="연결 품의서">
              <LookupSelect
                table="purchase_request"
                role={role}
                value={form['purchaseRequestId']}
                onChange={(v) => setField('purchaseRequestId', v)}
              />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
